        put3("fa", "LuminaInteractionHeader", "تعامل", "LuminaDoubleTapEdit", "برای ویرایش پیام خود دوبار ضربه بزنید", "LuminaDoubleTapEditInfo", "دوبار ضربه‌زدن روی یکی از پیام‌های خودتان به‌جای ارسال واکنش سریع، آن را برای ویرایش باز می‌کند.", "LuminaConfirmStartCall", "تأیید پیش از شروع تماس", "LuminaConfirmStartCallInfo", "پیش از برقراری تماس صوتی یا تصویری از شما تأیید می‌گیرد تا تماسی با ضربهٔ اشتباهی شروع نشود.", "LuminaCallConfirmTitle", "تماس شروع شود؟", "LuminaCallConfirmMessage", "می‌خواهید این تماس را همین حالا شروع کنید؟", "LuminaCallConfirmStart", "تماس", "LuminaMenuVisibilityHeader", "کنش‌های منوی پیام", "LuminaMenuVisibilityInfo", "انتخاب کنید هنگام فشار طولانی روی پیام چه کنش‌های استانداردی نمایش داده شود. خاموش‌کردن فقط آن را از منو پنهان می‌کند؛ قابلیت در جاهای دیگر همچنان کار می‌کند.", "LuminaMenuShowReply", "نمایش «پاسخ»", "LuminaMenuShowCopy", "نمایش «کپی»", "LuminaMenuShowForward", "نمایش «هدایت»", "LuminaMenuShowPin", "نمایش «سنجاق / برداشتن سنجاق»", "LuminaMenuShowReport", "نمایش «گزارش»", "LuminaMenuShowSaveDownload", "نمایش «ذخیره / دانلود»", "LuminaMessageFilter", "فیلتر پیام", "LuminaMessageFilterManage", "کلمات فیلترشده", "LuminaMessageFilterInfo", "پیام‌هایی که هر یک از این کلمات را داشته باشند فقط روی این دستگاه از گفتگو پنهان می‌شوند. چیزی حذف یا به Telegram ارسال نمی‌شود. برای نمایش همهٔ پیام‌ها فهرست را خالی بگذارید.", "LuminaMessageFilterTitle", "فیلتر پیام", "LuminaMessageFilterHeader", "کلمات پنهان", "LuminaMessageFilterAdd", "افزودن کلمه", "LuminaMessageFilterEdit", "ویرایش کلمه", "LuminaMessageFilterKeyword", "کلیدواژه");
        put3("tr", "LuminaInteractionHeader", "Etkileşim", "LuminaDoubleTapEdit", "Kendi mesajını düzenlemek için çift dokun", "LuminaDoubleTapEditInfo", "Kendi mesajlarından birine çift dokunmak, hızlı tepki göndermek yerine onu düzenlemeye açar.", "LuminaConfirmStartCall", "Arama başlatmadan önce onayla", "LuminaConfirmStartCallInfo", "Sesli veya görüntülü arama yapılmadan önce onay ister; böylece yanlışlıkla dokunuşla arama başlamaz.", "LuminaCallConfirmTitle", "Arama başlatılsın mı?", "LuminaCallConfirmMessage", "Bu aramayı şimdi başlatmak istiyor musun?", "LuminaCallConfirmStart", "Ara", "LuminaMenuVisibilityHeader", "Mesaj menüsü eylemleri", "LuminaMenuVisibilityInfo", "Bir mesaja uzun bastığında hangi standart eylemlerin görüneceğini seç. Birini kapatmak onu yalnızca menüden gizler; özellik başka yerlerde çalışmaya devam eder.", "LuminaMenuShowReply", "«Yanıtla»yı göster", "LuminaMenuShowCopy", "«Kopyala»yı göster", "LuminaMenuShowForward", "«İlet»i göster", "LuminaMenuShowPin", "«Sabitle / Sabiti kaldır»ı göster", "LuminaMenuShowReport", "«Şikayet et»i göster", "LuminaMenuShowSaveDownload", "«Kaydet / İndir»i göster", "LuminaMessageFilter", "Mesaj filtresi", "LuminaMessageFilterManage", "Filtrelenen kelimeler", "LuminaMessageFilterInfo", "Bu kelimelerden herhangi birini içeren mesajlar yalnızca bu cihazda sohbetten gizlenir. Hiçbir şey silinmez ve Telegram'a gönderilmez. Tüm mesajları göstermek için listeyi boş bırak.", "LuminaMessageFilterTitle", "Mesaj filtresi", "LuminaMessageFilterHeader", "Gizlenen kelimeler", "LuminaMessageFilterAdd", "Kelime ekle", "LuminaMessageFilterEdit", "Kelimeyi düzenle", "LuminaMessageFilterKeyword", "Anahtar kelime");
        put3("es", "LuminaInteractionHeader", "Interacción", "LuminaDoubleTapEdit", "Doble toque para editar tu mensaje", "LuminaDoubleTapEditInfo", "Tocar dos veces uno de tus propios mensajes lo abre para editar en lugar de enviar la reacción rápida.", "LuminaConfirmStartCall", "Confirmar antes de iniciar una llamada", "LuminaConfirmStartCallInfo", "Pide confirmación antes de una llamada de voz o vídeo, para que no se inicie con un toque accidental.", "LuminaCallConfirmTitle", "¿Iniciar llamada?", "LuminaCallConfirmMessage", "¿Quieres iniciar esta llamada ahora?", "LuminaCallConfirmStart", "Llamar", "LuminaMenuVisibilityHeader", "Acciones del menú del mensaje", "LuminaMenuVisibilityInfo", "Elige qué acciones estándar aparecen al mantener pulsado un mensaje. Desactivar una solo la oculta del menú; la función sigue disponible en otros lugares.", "LuminaMenuShowReply", "Mostrar «Responder»", "LuminaMenuShowCopy", "Mostrar «Copiar»", "LuminaMenuShowForward", "Mostrar «Reenviar»", "LuminaMenuShowPin", "Mostrar «Fijar / Dejar de fijar»", "LuminaMenuShowReport", "Mostrar «Denunciar»", "LuminaMenuShowSaveDownload", "Mostrar «Guardar / Descargar»", "LuminaMessageFilter", "Filtro de mensajes", "LuminaMessageFilterManage", "Palabras filtradas", "LuminaMessageFilterInfo", "Los mensajes que contengan cualquiera de estas palabras se ocultan del chat solo en este dispositivo. No se borra nada ni se envía nada a Telegram. Deja la lista vacía para mostrar todos los mensajes.", "LuminaMessageFilterTitle", "Filtro de mensajes", "LuminaMessageFilterHeader", "Palabras ocultas", "LuminaMessageFilterAdd", "Añadir palabra", "LuminaMessageFilterEdit", "Editar palabra", "LuminaMessageFilterKeyword", "Palabra clave");
        put3("pt-br", "LuminaInteractionHeader", "Interação", "LuminaDoubleTapEdit", "Toque duplo para editar sua mensagem", "LuminaDoubleTapEditInfo", "Tocar duas vezes em uma das suas mensagens a abre para edição em vez de enviar a reação rápida.", "LuminaConfirmStartCall", "Confirmar antes de iniciar uma chamada", "LuminaConfirmStartCallInfo", "Pede confirmação antes de uma chamada de voz ou vídeo, para que ela não comece com um toque acidental.", "LuminaCallConfirmTitle", "Iniciar chamada?", "LuminaCallConfirmMessage", "Deseja iniciar esta chamada agora?", "LuminaCallConfirmStart", "Chamar", "LuminaMenuVisibilityHeader", "Ações do menu da mensagem", "LuminaMenuVisibilityInfo", "Escolha quais ações padrão aparecem ao manter uma mensagem pressionada. Desativar uma apenas a oculta do menu; o recurso continua disponível em outros lugares.", "LuminaMenuShowReply", "Mostrar «Responder»", "LuminaMenuShowCopy", "Mostrar «Copiar»", "LuminaMenuShowForward", "Mostrar «Encaminhar»", "LuminaMenuShowPin", "Mostrar «Fixar / Desafixar»", "LuminaMenuShowReport", "Mostrar «Denunciar»", "LuminaMenuShowSaveDownload", "Mostrar «Salvar / Baixar»", "LuminaMessageFilter", "Filtro de mensagens", "LuminaMessageFilterManage", "Palavras filtradas", "LuminaMessageFilterInfo", "Mensagens que contenham qualquer uma dessas palavras ficam ocultas do chat apenas neste dispositivo. Nada é apagado nem enviado ao Telegram. Deixe a lista vazia para mostrar todas as mensagens.", "LuminaMessageFilterTitle", "Filtro de mensagens", "LuminaMessageFilterHeader", "Palavras ocultas", "LuminaMessageFilterAdd", "Adicionar palavra", "LuminaMessageFilterEdit", "Editar palavra", "LuminaMessageFilterKeyword", "Palavra-chave");
        put3("id", "LuminaInteractionHeader", "Interaksi", "LuminaDoubleTapEdit", "Ketuk dua kali untuk mengedit pesan Anda", "LuminaDoubleTapEditInfo", "Mengetuk dua kali salah satu pesan Anda sendiri akan membukanya untuk diedit, bukan mengirim reaksi cepat.", "LuminaConfirmStartCall", "Konfirmasi sebelum memulai panggilan", "LuminaConfirmStartCallInfo", "Meminta konfirmasi sebelum panggilan suara atau video, agar panggilan tidak dimulai oleh ketukan yang tidak sengaja.", "LuminaCallConfirmTitle", "Mulai panggilan?", "LuminaCallConfirmMessage", "Apakah Anda ingin memulai panggilan ini sekarang?", "LuminaCallConfirmStart", "Panggil", "LuminaMenuVisibilityHeader", "Tindakan menu pesan", "LuminaMenuVisibilityInfo", "Pilih tindakan standar yang muncul saat Anda menekan lama sebuah pesan. Menonaktifkan salah satu hanya menyembunyikannya dari menu; fiturnya tetap berfungsi di tempat lain.", "LuminaMenuShowReply", "Tampilkan «Balas»", "LuminaMenuShowCopy", "Tampilkan «Salin»", "LuminaMenuShowForward", "Tampilkan «Teruskan»", "LuminaMenuShowPin", "Tampilkan «Sematkan / Lepas sematan»", "LuminaMenuShowReport", "Tampilkan «Laporkan»", "LuminaMenuShowSaveDownload", "Tampilkan «Simpan / Unduh»", "LuminaMessageFilter", "Filter pesan", "LuminaMessageFilterManage", "Kata yang difilter", "LuminaMessageFilterInfo", "Pesan yang memuat salah satu kata ini disembunyikan dari obrolan hanya di perangkat ini. Tidak ada yang dihapus dan tidak ada yang dikirim ke Telegram. Biarkan daftar kosong untuk menampilkan semua pesan.", "LuminaMessageFilterTitle", "Filter pesan", "LuminaMessageFilterHeader", "Kata tersembunyi", "LuminaMessageFilterAdd", "Tambah kata", "LuminaMessageFilterEdit", "Edit kata", "LuminaMessageFilterKeyword", "Kata kunci");
