        put3("pt-br", "LuminaFolderTabsHeader", "Abas de pastas", "LuminaHideAllChatsTab", "Ocultar a aba «Todas as conversas»", "LuminaHideAllChatsTabInfo", "Remove a aba «Todas as conversas» da linha de pastas. O app abre na sua primeira pasta.", "LuminaWideFolderTabs", "Abas de pastas largas", "LuminaWideFolderTabsInfo", "Estica as abas de pastas para preencher uniformemente toda a largura da tela. Desligue para abas compactas do tamanho do texto.", "LuminaRememberLastFolder", "Lembrar a última pasta", "LuminaRememberLastFolderInfo", "Reabre na pasta que você estava vendo por último em vez de começar sempre em «Todas as conversas».");
        put3("id", "LuminaFolderTabsHeader", "Tab folder", "LuminaHideAllChatsTab", "Sembunyikan tab “Semua Obrolan”", "LuminaHideAllChatsTabInfo", "Menghapus tab “Semua Obrolan” dari baris folder. Aplikasi akan terbuka ke folder pertama Anda.", "LuminaWideFolderTabs", "Tab folder lebar", "LuminaWideFolderTabsInfo", "Meregangkan tab folder secara merata untuk memenuhi lebar penuh layar. Matikan untuk tab ringkas sesuai labelnya.", "LuminaRememberLastFolder", "Ingat folder terakhir", "LuminaRememberLastFolderInfo", "Buka kembali ke folder yang terakhir Anda lihat alih-alih selalu mulai dari “Semua Obrolan”.");
