        put3("zh-hant", "LuminaMediaPhotoHeader", "傳送圖片", "LuminaMediaPhotoQualityInfo", "傳送圖片時壓縮所用的 JPEG 品質。品質越高畫面越好，但耗用更多流量。預設值與 Telegram 相同。", "LuminaMediaSendLargePhotos", "傳送較大圖片", "LuminaMediaSendLargePhotosInfo", "以更高解析度、更少縮圖傳送圖片。仍使用 Telegram 的正常上傳，只改變尺寸與壓縮。", "LuminaMediaVideoHeader", "影片", "LuminaMediaSwipeVideoPip", "下滑進入子母畫面", "LuminaMediaSwipeVideoPipInfo", "影片全螢幕播放時，向下滑動即可縮成浮動子母畫面視窗。", "LuminaAppIconTitle", "應用程式圖示", "LuminaAppIconHeader", "選擇圖示", "LuminaAppIconInfo", "選擇顯示在主畫面的圖示。若已啟用偽裝，圖示會由偽裝接管，直到你關閉偽裝為止。");
