        put3("ru", "LuminaMediaPhotoHeader", "Отправляемые фото", "LuminaMediaPhotoQualityInfo", "Качество JPEG при сжатии отправляемых фото. Выше качество — лучше вид, но больше трафика. По умолчанию — как в Telegram.", "LuminaMediaSendLargePhotos", "Отправлять фото большего размера", "LuminaMediaSendLargePhotosInfo", "Отправлять фото в более высоком разрешении с меньшим уменьшением. Используется обычная загрузка Telegram, меняются лишь размер и сжатие.", "LuminaMediaVideoHeader", "Видео", "LuminaMediaSwipeVideoPip", "Свайп вниз для «картинка в картинке»", "LuminaMediaSwipeVideoPipInfo", "Когда видео воспроизводится на весь экран, проведите вниз, чтобы свернуть его в плавающее окно «картинка в картинке».", "LuminaAppIconTitle", "Значок приложения", "LuminaAppIconHeader", "Выбор значка", "LuminaAppIconInfo", "Выберите значок на главном экране. Если включена маскировка, она управляет значком, пока вы её не выключите.");
        put3("fa", "LuminaMediaPhotoHeader", "عکس‌های ارسالی", "LuminaMediaPhotoQualityInfo", "کیفیت JPEG هنگام فشرده‌سازی عکس‌هایی که می‌فرستید. کیفیت بالاتر بهتر دیده می‌شود اما داده بیشتری مصرف می‌کند. مقدار پیش‌فرض مانند تلگرام است.", "LuminaMediaSendLargePhotos", "ارسال عکس‌های بزرگ‌تر", "LuminaMediaSendLargePhotosInfo", "ارسال عکس‌ها با وضوح بالاتر و کوچک‌سازی کمتر. همچنان از بارگذاری عادی تلگرام استفاده می‌شود و فقط اندازه و فشرده‌سازی تغییر می‌کند.", "LuminaMediaVideoHeader", "ویدیو", "LuminaMediaSwipeVideoPip", "برای تصویر در تصویر به پایین بکشید", "LuminaMediaSwipeVideoPipInfo", "هنگام پخش تمام‌صفحه ویدیو، آن را به پایین بکشید تا در یک پنجره شناور تصویر در تصویر کوچک شود.", "LuminaAppIconTitle", "نماد برنامه", "LuminaAppIconHeader", "انتخاب نماد", "LuminaAppIconInfo", "نمادی را که در صفحه اصلی نمایش داده می‌شود انتخاب کنید. اگر استتار فعال باشد تا زمانی که آن را خاموش کنید نماد را در اختیار می‌گیرد.");
        put3("tr", "LuminaMediaPhotoHeader", "Gönderilen fotoğraflar", "LuminaMediaPhotoQualityInfo", "Gönderdiğiniz fotoğraflar sıkıştırılırken kullanılan JPEG kalitesi. Daha yüksek kalite daha iyi görünür ama daha çok veri kullanır. Varsayılan, Telegram ile aynıdır.", "LuminaMediaSendLargePhotos", "Daha büyük fotoğraf gönder", "LuminaMediaSendLargePhotosInfo", "Fotoğrafları daha yüksek çözünürlükte ve daha az küçülterek gönderir. Yine Telegram’ın normal yüklemesini kullanır; yalnızca boyut ve sıkıştırma değişir.", "LuminaMediaVideoHeader", "Video", "LuminaMediaSwipeVideoPip", "Pencere içinde pencere için aşağı kaydırın", "LuminaMediaSwipeVideoPipInfo", "Video tam ekran oynatılırken aşağı kaydırarak onu yüzen bir pencere içinde pencere penceresine küçültün.", "LuminaAppIconTitle", "Uygulama simgesi", "LuminaAppIconHeader", "Simge seç", "LuminaAppIconInfo", "Ana ekranınızda görünen simgeyi seçin. Bir kılık etkinse siz kapatana kadar simgeyi o yönetir.");
        put3("es", "LuminaMediaPhotoHeader", "Fotos enviadas", "LuminaMediaPhotoQualityInfo", "Calidad JPEG al comprimir las fotos que envías. Más calidad se ve mejor pero usa más datos. El valor por defecto coincide con Telegram.", "LuminaMediaSendLargePhotos", "Enviar fotos más grandes", "LuminaMediaSendLargePhotosInfo", "Envía las fotos con mayor resolución y menos reducción. Sigue usando la subida normal de Telegram; solo cambian el tamaño y la compresión.", "LuminaMediaVideoHeader", "Vídeo", "LuminaMediaSwipeVideoPip", "Desliza hacia abajo para imagen en imagen", "LuminaMediaSwipeVideoPipInfo", "Mientras un vídeo se reproduce a pantalla completa, deslízalo hacia abajo para reducirlo a una ventana flotante de imagen en imagen.", "LuminaAppIconTitle", "Icono de la app", "LuminaAppIconHeader", "Elegir icono", "LuminaAppIconInfo", "Elige el icono que aparece en tu pantalla de inicio. Si hay un disfraz activo, este controla el icono hasta que lo desactives.");
        put3("pt-br", "LuminaMediaPhotoHeader", "Fotos enviadas", "LuminaMediaPhotoQualityInfo", "Qualidade JPEG ao comprimir as fotos que você envia. Mais qualidade fica melhor, mas usa mais dados. O padrão é igual ao do Telegram.", "LuminaMediaSendLargePhotos", "Enviar fotos maiores", "LuminaMediaSendLargePhotosInfo", "Envia as fotos em resolução maior e com menos redução. Ainda usa o envio normal do Telegram; só mudam o tamanho e a compressão.", "LuminaMediaVideoHeader", "Vídeo", "LuminaMediaSwipeVideoPip", "Deslize para baixo para imagem sobre imagem", "LuminaMediaSwipeVideoPipInfo", "Enquanto um vídeo é reproduzido em tela cheia, deslize-o para baixo para reduzi-lo a uma janela flutuante de imagem sobre imagem.", "LuminaAppIconTitle", "Ícone do app", "LuminaAppIconHeader", "Escolher ícone", "LuminaAppIconInfo", "Escolha o ícone exibido na sua tela inicial. Se um disfarce estiver ativo, ele assume o ícone até você desativá-lo.");
        put3("id", "LuminaMediaPhotoHeader", "Foto keluar", "LuminaMediaPhotoQualityInfo", "Kualitas JPEG saat mengompres foto yang Anda kirim. Makin tinggi makin bagus tetapi memakai lebih banyak data. Nilai bawaan sama seperti Telegram.", "LuminaMediaSendLargePhotos", "Kirim foto lebih besar", "LuminaMediaSendLargePhotosInfo", "Mengirim foto dengan resolusi lebih tinggi dan pengecilan lebih sedikit. Tetap memakai unggahan normal Telegram; hanya ukuran dan kompresi yang berubah.", "LuminaMediaVideoHeader", "Video", "LuminaMediaSwipeVideoPip", "Geser ke bawah untuk gambar dalam gambar", "LuminaMediaSwipeVideoPipInfo", "Saat video diputar layar penuh, geser ke bawah untuk mengecilkannya menjadi jendela gambar dalam gambar yang mengambang.", "LuminaAppIconTitle", "Ikon aplikasi", "LuminaAppIconHeader", "Pilih ikon", "LuminaAppIconInfo", "Pilih ikon yang tampil di layar utama Anda. Jika penyamaran aktif, ia mengambil alih ikon sampai Anda mematikannya.");
