    // Batch 9 (#21 large-file transfer boost) translations live in their own method so the
    // static initializer stays under the JVM 64KB per-method bytecode limit. English is the
    // strings.xml fallback via LocaleController.
    private static void loadBatch9() {
        put3("zh-hans", "LuminaMediaTransferHeader", "大文件传输", "LuminaMediaTransferBoost", "加速大文件传输（实验性）", "LuminaMediaTransferBoostInfo", "使用更大的上传和下载分块（每个上传分块最大 512 KB，每个下载分块最大 1 MB），让大文件用更少的请求传输。实验性功能——如果你的网络下上传或下载出现异常，请关闭。关闭时与 Telegram 完全一致。");
        put3("zh-hant", "LuminaMediaTransferHeader", "大型檔案傳輸", "LuminaMediaTransferBoost", "加速大型檔案傳輸（實驗性）", "LuminaMediaTransferBoostInfo", "使用更大的上傳和下載分塊（每個上傳分塊最大 512 KB，每個下載分塊最大 1 MB），讓大型檔案以更少的請求傳輸。實驗性功能——若你的網路上傳或下載出現異常，請關閉。關閉時與 Telegram 完全一致。");
        put3("ar", "LuminaMediaTransferHeader", "نقل الملفات الكبيرة", "LuminaMediaTransferBoost", "تسريع نقل الملفات الكبيرة (تجريبي)", "LuminaMediaTransferBoostInfo", "استخدام أجزاء رفع وتنزيل أكبر (حتى 512 كيلوبايت لكل جزء رفع و1 ميجابايت لكل جزء تنزيل) لنقل الملفات الكبيرة بعدد أقل من الطلبات. ميزة تجريبية — أوقفها إذا حدث خلل في الرفع أو التنزيل على اتصالك. عند الإيقاف تطابق تيليجرام تماماً.");
        put3("ru", "LuminaMediaTransferHeader", "Передача больших файлов", "LuminaMediaTransferBoost", "Ускорить передачу больших файлов (эксперимент)", "LuminaMediaTransferBoostInfo", "Использовать более крупные части при загрузке и скачивании (до 512 КБ на часть при отправке и до 1 МБ при скачивании), чтобы большие файлы передавались меньшим числом запросов. Экспериментально — отключите, если отправка или скачивание работают нестабильно на вашем соединении. В выключенном состоянии всё точно как в Telegram.");
        put3("fa", "LuminaMediaTransferHeader", "انتقال فایل‌های بزرگ", "LuminaMediaTransferBoost", "تسریع انتقال فایل‌های بزرگ (آزمایشی)", "LuminaMediaTransferBoostInfo", "استفاده از بخش‌های بزرگ‌تر برای بارگذاری و دانلود (تا ۵۱۲ کیلوبایت برای هر بخش بارگذاری و ۱ مگابایت برای هر بخش دانلود) تا فایل‌های بزرگ با درخواست‌های کمتری منتقل شوند. آزمایشی — اگر بارگذاری یا دانلود روی اتصال شما درست کار نکرد آن را خاموش کنید. در حالت خاموش دقیقاً مانند تلگرام است.");
        put3("tr", "LuminaMediaTransferHeader", "Büyük dosya aktarımı", "LuminaMediaTransferBoost", "Büyük aktarımları hızlandır (deneysel)", "LuminaMediaTransferBoostInfo", "Büyük dosyaların daha az istekle taşınması için daha büyük yükleme ve indirme parçaları kullanır (yükleme parçası başına en fazla 512 KB, indirme parçası başına 1 MB). Deneysel — bağlantınızda yükleme veya indirme düzgün çalışmazsa kapatın. Kapalıyken Telegram ile birebir aynıdır.");
        put3("es", "LuminaMediaTransferHeader", "Transferencia de archivos grandes", "LuminaMediaTransferBoost", "Acelerar transferencias grandes (experimental)", "LuminaMediaTransferBoostInfo", "Usa partes de subida y descarga más grandes (hasta 512 KB por parte de subida y 1 MB por parte de descarga) para mover archivos grandes con menos solicitudes. Experimental: desactívalo si la subida o la descarga fallan en tu conexión. Desactivado coincide exactamente con Telegram.");
        put3("pt-br", "LuminaMediaTransferHeader", "Transferência de arquivos grandes", "LuminaMediaTransferBoost", "Acelerar transferências grandes (experimental)", "LuminaMediaTransferBoostInfo", "Usa partes de envio e download maiores (até 512 KB por parte de envio e 1 MB por parte de download) para mover arquivos grandes com menos solicitações. Experimental — desative se o envio ou o download apresentarem problemas na sua conexão. Desativado é idêntico ao Telegram.");
        put3("id", "LuminaMediaTransferHeader", "Transfer file besar", "LuminaMediaTransferBoost", "Percepat transfer besar (eksperimental)", "LuminaMediaTransferBoostInfo", "Menggunakan bagian unggah dan unduh yang lebih besar (hingga 512 KB per bagian unggah dan 1 MB per bagian unduh) agar file besar berpindah dengan lebih sedikit permintaan. Eksperimental — matikan jika unggahan atau unduhan bermasalah pada koneksi Anda. Saat mati, sama persis dengan Telegram.");
    }

